import { describe, expect, it, vi } from 'vitest'
import { gunzipSync } from 'node:zlib'
import { createHash } from 'node:crypto'
import { performance } from 'node:perf_hooks'
import type { Client } from 'pg'
import { prepareRetainedCatalog, assertRetainedCatalogCurrent, type RetainedCatalogPreparation, type RetainedCatalogCurrentIdentity } from '../../migrations/shared-forward/retained-authority-native-catalog.js'
import { RETAINED_NATIVE_SOURCE_PROFILE_SHA256 } from '../../migrations/shared-forward/retained-authority-native-profile.js'

// BEGIN IMMUTABLE NATIVE TRANSPORT FIXTURES
// Exact SELECT-only prototype observations; compressed solely to avoid duplicating multi-megabyte native pg_node_tree strings.
// Fixture bytes are SHA-bound, every replay query must match its captured SQL SHA, and policy remains independently source-derived.
const NATIVE_FIXTURES = {"13":{"sha256":"723a1e805f02856f9e5fea3819a9f928385546ce354669d96860d683863c4adb","gzipBase64":""},"17":{"sha256":"d9b60f346a84aba093201cbd76504e888fb2391eec77515babe01f9f70751512","gzipBase64":""}}
// END IMMUTABLE NATIVE TRANSPORT FIXTURES
const identity = { database: 'synthetic', databaseOid: '20001', role: 'maintainer', roleOid: '20002', serverAddress: '172.17.0.8', serverPort: '5432', serverVersionNum: '130023' as const }
const config = (): RetainedCatalogPreparation => ({
  identity, configSha256: 'a'.repeat(64), sourceProfileSha256: RETAINED_NATIVE_SOURCE_PROFILE_SHA256,
  reviewSha256: 'b'.repeat(64), enclosingRegistry: { scope: 'isolated-three-object-prototype', sourceSha256: 'c'.repeat(64) },
  tablespace: { name: 'pg_default', oid: '1663', ownerOid: '10' },
})
describe('finite retained native catalog preparation', () => {
  it('prepares an opaque finite source profile outside SQL without authority fields', () => {
    const prepared = prepareRetainedCatalog(config())
    expect(Object.keys(prepared)).toEqual([])
    expect(JSON.stringify(prepared)).toBe('{}')
  })
  it('refuses unreviewed source hashes before SQL', () => {
    expect(() => prepareRetainedCatalog({ ...config(), sourceProfileSha256: 'd'.repeat(64) })).toThrow('source_profile')
  })
  it('refuses fabricated serialized prepared objects before SQL', async () => {
    await expect(assertRetainedCatalogCurrent({} as Client, {} as never, { ...identity, configSha256:'a'.repeat(64), sourceProfileSha256:RETAINED_NATIVE_SOURCE_PROFILE_SHA256, reviewSha256:'b'.repeat(64), enclosingRegistrySha256:'c'.repeat(64) })).rejects.toThrow('prepared_profile')
  })
})

type NativeRow = Record<string, any>
interface Frame { name: string; sqlSha256: string; output: { row_count: string; wire_bytes: string; wire: string | null } }
function digest(text: string | Buffer): string { return createHash('sha256').update(text).digest('hex') }
const FIXTURES = Object.fromEntries((['13','17'] as const).map(major => {
  const raw = gunzipSync(Buffer.from(NATIVE_FIXTURES[major].gzipBase64, 'base64'))
  expect(digest(raw)).toBe(NATIVE_FIXTURES[major].sha256)
  return [major, JSON.parse(raw.toString()) as Frame[]]
})) as Record<'13'|'17',Frame[]>
function page(frames: Frame[], name: string): Frame { const f = frames.find(f => f.name === name); if (!f) throw Error('fixture_page_missing/' + name); return f }
function contents(frame: Frame): NativeRow[] { return (JSON.parse(frame.output.wire!) as { rows: NativeRow[] }).rows }
function modify(frames: Frame[], name: string, edit: (rows: NativeRow[]) => void): void {
  const frame = page(frames, name), rows = contents(frame)
  edit(rows)
  const wire = JSON.stringify({ rowCount: String(rows.length), rows })
  frame.output = { row_count: String(rows.length), wire_bytes: String(Buffer.byteLength(wire)), wire }
}
function replay(major: '13'|'17', edit?: (frames: Frame[]) => void) {
  const frames = structuredClone(FIXTURES[major]), row = contents(frames[0]!)[0]!
  const identity: RetainedCatalogPreparation['identity'] = { database: row.database, databaseOid: row.database_oid, role: row.role, roleOid: row.role_oid, serverAddress: row.server_address, serverPort: row.server_port, serverVersionNum: row.server_version_num }
  edit?.(frames)
  let index = 0, status = 'T'
  const client = {
    processID: Number(row.backend_pid),
    getTransactionStatus: () => status,
    query: async (sql: string) => {
      if (sql === "SELECT pg_catalog.current_setting('search_path'::pg_catalog.text) OPERATOR(pg_catalog.=) 'pg_catalog'::pg_catalog.text AS safe_path") return { rows:[{safe_path:true}] }
      const frame = frames[index++]
      expect(frame, 'unexpected query/transaction/connect mutation').toBeDefined()
      expect(digest(sql), 'actual query differs from source-bound immutable capture/' + frame!.name).toBe(frame!.sqlSha256)
      return { rows: [structuredClone(frame!.output)] }
    },
  } as unknown as Client
  const prepared = prepareRetainedCatalog({ ...config(), identity })
  const current: RetainedCatalogCurrentIdentity = { ...identity, configSha256: config().configSha256, sourceProfileSha256: config().sourceProfileSha256, reviewSha256: config().reviewSha256, enclosingRegistrySha256: config().enclosingRegistry.sourceSha256 }
  return { client, prepared, identity: current, frames, calls: () => index, setStatus: (value: string) => { status = value } }
}
for (const major of ['13','17'] as const) describe('PG' + major + ' immutable native-row replay (no DB tamper)', () => {
  it('accepts the complete independent captured transport with 71/72 native properties and no authority fields', async () => {
    const r = replay(major)
    expect(contents(page(r.frames, 'functions'))).toHaveLength(major === '13' ? 71 : 72)
    await expect(assertRetainedCatalogCurrent(r.client, r.prepared, r.identity)).resolves.toBeUndefined()
    expect(r.calls()).toBe(r.frames.length)
  })
  const nativeFunctions = contents(page(FIXTURES[major], 'functions')).map(r => String(r.proname) + '(' + r.argument_types.join(',') + ')')
  for (const signature of nativeFunctions) {
    const matching = (row: NativeRow) => String(row.proname) + '(' + row.argument_types.join(',') + ')' === signature
    it('refuses missing native function ' + signature, async () => {
      const r = replay(major, frames => modify(frames, 'functions', rows => { const i = rows.findIndex(matching); expect(i).toBeGreaterThanOrEqual(0); rows.splice(i,1) }))
      await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('retained_catalog_')
    })
    it('refuses native implementation property drift ' + signature, async () => {
      const r = replay(major, frames => modify(frames,'functions',rows => { rows.find(matching)!.fields.prosrc += '_altered' }))
      await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('function_property')
    })
  }
  const mutations: [string,string,(rows: NativeRow[]) => void][] = [
    ['extra heap','enclosingObjects',r => r.push({kind:'relation',name:'extra_helper',subtype:'r'})],
    ['unknown enclosing function','enclosingObjects',r => r.push({kind:'function',name:'hidden',subtype:'f'})],
    ['unknown enclosing domain','enclosingObjects',r => r.push({kind:'type',name:'hidden',subtype:'d'})],
    ['unknown lifecycle relation','enclosingObjects',r => r.push({kind:'relation',name:'future_team',subtype:'r'})],
    ['missing column','columns',r => { r.pop() }],
    ['NULL statistics target','columns',r => { r[0]!.attstattarget=null }],
    ['attribute dropped field','allAttributes',r => { delete r[0]!.fields.attstorage }],
    ['attribute unknown field','allAttributes',r => { r[0]!.fields.unreviewed=true }],
    ['authored attribute nullability','allAttributes',r => { r.find(x => x.schema_name==='shared')!.fields.attnotnull=false }],
    ['wrong relation kind','relationStorage',r => { r.find(x => x.schema_name==='shared' && x.relkind==='r')!.relkind='v' }],
    ['TOAST owner drift','relationStorage',r => { r.find(x => x.schema_name==='pg_toast')!.owner_oid='999' }],
    ['tablespace drift','relationStorage',r => { r[0]!.explicit_tablespace_oid='999' }],
    ['raw relation unknown field','rawRelations',r => { r[0]!.fields.new_native_field=false }],
    ['extra index','allIndexFields',r => { r.push(structuredClone(r[0]!)) }],
    ['invalid index','allIndexFields',r => { r[0]!.native_index_fields.indisvalid=false }],
    ['unknown index field','allIndexFields',r => { r[0]!.native_index_fields.unreviewed=false }],
    ['index key order','allIndexFields',r => { const a=r.find(x => x.native_index_fields.indkey.length>1)!; a.native_index_fields.indkey.reverse() }],
    ['wrong opclass namespace','classes',r => { r[0]!.schema_name='foreign' }],
    ['wrong opfamily link','classes',r => { r[0]!.fields.opcfamily='999' }],
    ['non-default opclass','classes',r => { r[0]!.fields.opcdefault=false }],
    ['operator function link','operators',r => { r[0]!.code_oid='999' }],
    ['operator negator link','operators',r => { r[0]!.fields.oprnegate='999' }],
    ['support slot missing','familyFunctions',r => { r.pop() }],
    ['wrong support function','familyFunctions',r => { r[0]!.function_oid='999' }],
    ['FK equality link','fkOperators',r => { r[0]!.operator_oid='999' }],
    ['FK deferred','constraints',r => { r.find(x => x.contype==='f')!.condeferrable=true }],
    ['constraint missing field','rawConstraints',r => { delete r[0]!.fields.conparentid }],
    ['constraint unknown field','rawConstraints',r => { r[0]!.fields.new_native_field=null }],
    ['extra orphan trigger','rawTriggers',r => { const x=structuredClone(r[0]!); x.trigger_oid='999'; x.fields.tgconstraint='0';r.push(x) }],
    ['disabled RI','triggerLinks',r => { r[0]!.tgenabled='D' }],
    ['inherited RI','triggerLinks',r => { r[0]!.tgparentid='999' }],
    ['RI current function link','rawTriggers',r => { r[0]!.fields.tgfoid='999' }],
    ['TOAST extra attribute','toastAllAttributes',r => { const x=structuredClone(r[0]!);x.fields.attnum=4;r.push(x) }],
    ['TOAST major-specific statistics','toastAllAttributes',r => { r[0]!.fields.attstattarget=major==='13'?null:-1 }],
    ['generated type missing field','nativeTypes',r => { delete r[0]!.fields.typrelid }],
    ['generated type callback link','nativeTypes',r => { r[0]!.input_oid='999' }],
    ['generated type PUBLIC ACL representation','nativeTypes',r => { r[0]!.fields.typacl=[] }],
    ['missing actual dependency','dependencies',r => { r.pop() }],
    ['extra inbound dependency','dependencies',r => { r.push({class_name:'pg_proc',objid:'999',objsubid:'0',ref_class:'pg_class',refobjid:r[0]!.refobjid,refobjsubid:'0',deptype:'n'}) }],
    ['extension dependency','dependencies',r => { r[0]!.ref_class='pg_extension';r[0]!.deptype='e' }],
    ['extra native dependency','nativeDependencies',r => { r.push({class_name:'pg_proc',objid:'999',objsubid:'0',ref_class:'pg_extension',refobjid:'888',refobjsubid:'0',deptype:'e'}) }],
    ['builtin type owner substitution','nativeTypeIdentities',r => { r[0]!.typowner='999' }],
    ['native function unknown field','functions',r => { r[0]!.fields.new_native_field=null }],
    ['native function NULL security','functions',r => { r[0]!.fields.prosecdef=null }],
    ['CHECK non-native function namespace','checkFunctionReferences',r => { r[0]!.schema_name='extension' }],
    ['CHECK native function owner','checkFunctionReferences',r => { r[0]!.proowner='999' }],
    ['CHECK native OID link substitution','checkFunctionReferences',r => { r[0]!.function_oid='999' }],
    ['CHECK native operator OID link','checkOperatorReferences',r => { r[0]!.function_oid='999' }],
    ['schema ACL CREATE bypass','namespaces',r => { r.find(x => x.nspname==='shared' && x.privilege_type==='CREATE')!.grantee='0' }],
    ['ACL grantee drift','acl',r => { r.find(x => x.kind==='relation')!.grantee='0' }],
    ['ACL grant-option drift','acl',r => { r[0]!.is_grantable=true }],
    ['native PUBLIC USAGE removed','acl',r => { r.splice(r.findIndex(x => x.kind==='type' && x.grantee==='0'),1) }],
    ['database CREATE bypass','databaseAcl',r => { r.find(x => x.privilege_type==='CREATE')!.grantee='0' }],
    ['default ACL mutation','defaultAcls',r => { r.push({defaclrole:'10',defaclobjtype:'r',defaclacl:['public=arwdDxt/postgres']}) }],
    ['role SET/INHERIT access bypass','memberships',r => { r.push({fields:{roleid:'10',member:'999',grantor:'10',admin_option:false,inherit_option:true,set_option:true},role_name:'postgres',member_name:'attacker'}) }],
    ['current role unknown field','roles',r => { r[0]!.fields.new_field=false }],
    ['current role BYPASSRLS drift','roles',r => { r[0]!.fields.rolbypassrls=false }],
  ]
  for (const [label, family, mutate] of mutations) it('refuses ' + label, async () => {
    const r = replay(major, frames => modify(frames, family, mutate))
    await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('retained_catalog_')
  })
  for (const [label,name,from,to] of [
    ['UNKNOWN handling','ra1_r_01','COALESCE','NULLIF'],
    ['true readiness','ra1_r_05','IS FALSE','IS TRUE'],
    ['enum branch','ra1_r_04',"'sealed'","'seale'"],
    ['JSON schema field','ra1_i_04','schema','schemax'],
    ['decimal bound','ra1_r_02','1000000000000000000000000000000','1000000000000000000000000000001'],
  ]) it('refuses whole CHECK definition change: ' + label, async () => {
    const r = replay(major, frames => modify(frames,'constraints',rows => {
      const c = rows.find(x => x.conname===name)!, prior = c.definition
      c.definition = c.definition.replace(from,to);expect(c.definition).not.toBe(prior)
    }))
    await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('constraint_whole_definition/definition')
  })
  for (const [key,value] of [['read_only','on'],['isolation','repeatable read'],['search_path','shared, pg_catalog'],['statement_timeout','0'],['lock_timeout','2s'],['idle_timeout','0'],['session_role','other'],['database_oid','999'],['server_address','127.0.0.2']]) it('refuses current client setting or identity ' + key, async () => {
    const r = replay(major, frames => modify(frames,'identity',rows => { rows[0]![key!]=value }))
    await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('retained_catalog_')
  })
  it('refuses final client identity drift after all catalog pages', async () => {
    const r = replay(major, frames => modify(frames,'identityFinal',rows => { rows[0]!.backend_pid='999' }))
    await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('backend_binding')
  })
  it('refuses a different physical client for the prepared profile', async () => {
    const r = replay(major)
    await assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)
    await expect(assertRetainedCatalogCurrent(replay(major).client,r.prepared,r.identity)).rejects.toThrow('physical_client_binding')
  })
  for (const status of ['I','E']) it('refuses idle/failed transaction status ' + status + ' before SQL', async () => {
    const r = replay(major);r.setStatus(status)
    await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('active_transaction')
    expect(r.calls()).toBe(0)
  })
  for (const [label,metadata] of [
    ['1025-row server refusal',{row_count:'1025',wire_bytes:'100',wire:null}],
    ['8MiB server refusal',{row_count:'1',wire_bytes:'8388609',wire:null}],
    ['incorrect transfer byte length',{row_count:'1',wire_bytes:'3',wire:'{}'}],
    ['truncated row-count response',{row_count:'1',wire_bytes:'26',wire:'{"rowCount":"1","rows":[]}'}],
  ] as const) it('refuses ' + label, async () => {
    const r = replay(major,frames => { frames[0]!.output={...metadata} })
    await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('retained_catalog_wire_')
  })
  it('refuses an elapsed audit deadline before another client query', async () => {
    const r = replay(major);await assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)
    const old = performance.now(), now = vi.spyOn(performance,'now').mockReturnValue(old+10001)
    try { await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('physical_deadline') }
    finally { now.mockRestore() }
  })
})

for (const major of ['13','17'] as const) describe('PG' + major + ' cross-window link regressions', () => {
  it('refuses an unresolved qualified opclass input schema', async () => {
    const r = replay(major, frames => modify(frames,'indexKeys',rows => { rows[0]!.opclass_input_type_schema='foreign' }))
    await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('retained_catalog_')
  })
  it('refuses TOAST attribute raw OID not linked to the same resolved type', async () => {
    const r = replay(major, frames => modify(frames,'toastAllAttributes',rows => { rows[0]!.fields.atttypid='999' }))
    await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('retained_catalog_')
  })
  it('refuses coherent pg_class index attribute-count drift across both raw views', async () => {
    const r = replay(major, frames => {
      const index = contents(page(frames,'relationStorage')).find(x => x.relkind==='i')!.relation_oid
      modify(frames,'relationLinks',rows => { rows.find(x => x.relation_oid===index)!.relnatts='99' })
      modify(frames,'rawRelations',rows => { rows.find(x => x.relation_oid===index)!.fields.relnatts=99 })
    })
    await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('retained_catalog_')
  })
})

for (const key of ['configSha256','sourceProfileSha256','reviewSha256','enclosingRegistrySha256'] as const) it('refuses stale current ' + key + ' before SQL', async () => {
  const r = replay('13')
  await expect(assertRetainedCatalogCurrent(r.client,r.prepared,{...r.identity,[key]:'e'.repeat(64)})).rejects.toThrow('current_configuration_binding')
  expect(r.calls()).toBe(0)
})
it('refuses current transaction reuse with a different xact_start', async () => {
  const r = replay('13',frames => modify(frames,'identityFinal',rows => { rows[0]!.transaction_start='2099-01-01 00:00:00+00' }))
  await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('transaction_binding')
})
it('rejects unknown preparation and identity fields', () => {
  expect(() => prepareRetainedCatalog({...config(), extra:true} as RetainedCatalogPreparation)).toThrow('preparation/fields')
  expect(() => prepareRetainedCatalog({...config(), identity:{...identity,extra:'unknown'}} as RetainedCatalogPreparation)).toThrow('identity_binding/fields')
})

for (const major of ['13','17'] as const) it('PG' + major + ' refuses native language OID substitution despite matching display name', async () => {
  const r = replay(major, frames => modify(frames,'functions',rows => { rows[0]!.fields.prolang='999' }))
  await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('function_oid_links/prolang')
})

it('refuses an unsafe search path using a qualified bounded scalar preflight before catalog SQL', async () => {
  const r = replay('13'), query = r.client.query.bind(r.client)
  r.client.query = (async (sql: string) => sql.startsWith('SELECT pg_catalog.current_setting') ? { rows:[{safe_path:false}] } : query(sql)) as typeof r.client.query
  await expect(assertRetainedCatalogCurrent(r.client,r.prepared,r.identity)).rejects.toThrow('safe_search_path')
  expect(r.calls()).toBe(0)
})
